    !isempty(x.informed_entity) && (encoded_size += PB._encoded_size(x.informed_entity, 5))
    x.cause != var"Alert.Cause".UNKNOWN_CAUSE && (encoded_size += PB._encoded_size(x.cause, 6))
    x.effect != var"Alert.Effect".UNKNOWN_EFFECT && (encoded_size += PB._encoded_size(x.effect, 7))
    !isnothing(x.url) && (encoded_size += PB._encoded_size(x.url, 8))
