struct FeedEntity
    id::String
    is_deleted::Bool
    trip_update::Union{Nothing, TripUpdate}
    vehicle::Union{Nothing, VehiclePosition}
    alert::Union{Nothing, Alert}
    shape::Union{Nothing, Shape}
    stop::Union{Nothing, Stop}
    trip_modifications::Union{Nothing, TripModifications}
end
PB.extendable_field_numbers(::Type{FeedEntity}) = Union{Int, UnitRange{Int}}[1000:1999, 9000:9999]
PB.default_values(::Type{FeedEntity}) = (; id = "", is_deleted = false, trip_update = nothing, vehicle = nothing, alert = nothing, shape = nothing, stop = nothing, trip_modifications = nothing)
PB.field_numbers(::Type{FeedEntity}) = (; id = 1, is_deleted = 2, trip_update = 3, vehicle = 4, alert = 5, shape = 6, stop = 7, trip_modifications = 8)

function PB.decode(d::PB.AbstractProtoDecoder, ::Type{<:FeedEntity})
    id = ""
    is_deleted = false
    trip_update = Ref{Union{Nothing, TripUpdate}}(nothing)
    vehicle = Ref{Union{Nothing, VehiclePosition}}(nothing)
    alert = Ref{Union{Nothing, Alert}}(nothing)
    shape = Ref{Union{Nothing, Shape}}(nothing)
    stop = Ref{Union{Nothing, Stop}}(nothing)
    trip_modifications = Ref{Union{Nothing, TripModifications}}(nothing)
    while !PB.message_done(d)
        field_number, wire_type = PB.decode_tag(d)
        if field_number == 1
            id = PB.decode(d, String)
        elseif field_number == 2
            is_deleted = PB.decode(d, Bool)
        elseif field_number == 3
            PB.decode!(d, trip_update)
        elseif field_number == 4
            PB.decode!(d, vehicle)
        elseif field_number == 5
            PB.decode!(d, alert)
        elseif field_number == 6
            PB.decode!(d, shape)
        elseif field_number == 7
            PB.decode!(d, stop)
        elseif field_number == 8
            PB.decode!(d, trip_modifications)
        else
            Base.skip(d, wire_type)
        end
    end
    return FeedEntity(id, is_deleted, trip_update[], vehicle[], alert[], shape[], stop[], trip_modifications[])
end

function PB.encode(e::PB.AbstractProtoEncoder, x::FeedEntity)
    initpos = position(e.io)
    PB.encode(e, 1, x.id)
    x.is_deleted != false && PB.encode(e, 2, x.is_deleted)
    !isnothing(x.trip_update) && PB.encode(e, 3, x.trip_update)
    !isnothing(x.vehicle) && PB.encode(e, 4, x.vehicle)
    !isnothing(x.alert) && PB.encode(e, 5, x.alert)
    !isnothing(x.shape) && PB.encode(e, 6, x.shape)
    !isnothing(x.stop) && PB.encode(e, 7, x.stop)
    !isnothing(x.trip_modifications) && PB.encode(e, 8, x.trip_modifications)
    return position(e.io) - initpos
end
function PB._encoded_size(x::FeedEntity)
    encoded_size = 0
    encoded_size += PB._encoded_size(x.id, 1)
    x.is_deleted != false && (encoded_size += PB._encoded_size(x.is_deleted, 2))
    !isnothing(x.trip_update) && (encoded_size += PB._encoded_size(x.trip_update, 3))
    !isnothing(x.vehicle) && (encoded_size += PB._encoded_size(x.vehicle, 4))
    !isnothing(x.alert) && (encoded_size += PB._encoded_size(x.alert, 5))
    !isnothing(x.shape) && (encoded_size += PB._encoded_size(x.shape, 6))
    !isnothing(x.stop) && (encoded_size += PB._encoded_size(x.stop, 7))
    !isnothing(x.trip_modifications) && (encoded_size += PB._encoded_size(x.trip_modifications, 8))
    return encoded_size
end

struct FeedMessage
    header::FeedHeader
    entity::Vector{FeedEntity}
end
PB.extendable_field_numbers(::Type{FeedMessage}) = Union{Int, UnitRange{Int}}[1000:1999, 9000:9999]
PB.default_values(::Type{FeedMessage}) = (; header, entity = Vector{FeedEntity}())
PB.field_numbers(::Type{FeedMessage}) = (; header = 1, entity = 2)

function PB.decode(d::PB.AbstractProtoDecoder, ::Type{<:FeedMessage})
    header = Ref{FeedHeader}()
    entity = PB.BufferedVector{FeedEntity}()
    while !PB.message_done(d)
        field_number, wire_type = PB.decode_tag(d)
        if field_number == 1
            PB.decode!(d, header)
        elseif field_number == 2
            PB.decode!(d, entity)
        else
            Base.skip(d, wire_type)
        end
    end
    return FeedMessage(header[], entity[])
end

function PB.encode(e::PB.AbstractProtoEncoder, x::FeedMessage)
    initpos = position(e.io)
    PB.encode(e, 1, x.header)
    !isempty(x.entity) && PB.encode(e, 2, x.entity)
    return position(e.io) - initpos
end
function PB._encoded_size(x::FeedMessage)
    encoded_size = 0
    encoded_size += PB._encoded_size(x.header, 1)
    !isempty(x.entity) && (encoded_size += PB._encoded_size(x.entity, 2))
    return encoded_size
end
